166	/// 手动解析比较查询串（percent-decode 后取 from / to，均必须是正整数）。
167	fn parse_diff_query(uri: &Uri) -> Result<DiffParams, String> {
168	    let mut from: Option<u64> = None;
169	    let mut to: Option<u64> = None;
170	    if let Some(query) = uri.query() {
171	        for pair in query.split('&') {
172	            let Some((raw_name, raw_value)) = pair.split_once('=') else {
173	                return Err(format!("非法查询参数: {pair}"));
174	            };
175	            let name = percent_decode_str(raw_name).decode_utf8_lossy();
176	            let value = percent_decode_str(raw_value).decode_utf8_lossy();
177	            let parse_version = |label: &str| -> Result<u64, String> {
178	                let parsed: u64 = value
179	                    .parse()
180	                    .map_err(|_| format!("{label} 必须是正整数: {value}"))?;
181	                if parsed == 0 {
182	                    return Err(format!("{label} 必须是正整数: {value}"));
183	                }
184	                Ok(parsed)
185	            };
186	            match name.as_ref() {
187	                "from" => from = Some(parse_version("from")?),
188	                "to" => to = Some(parse_version("to")?),
189	                other => return Err(format!("未知查询参数: {other}")),
190	            }
191	        }
192	    }
193	    match (from, to) {
194	        (Some(from), Some(to)) => Ok(DiffParams { from, to }),
195	        (None, _) => Err("缺少必填查询参数 from".to_owned()),
196	        (_, None) => Err("缺少必填查询参数 to".to_owned()),
197	    }
198	}
