        assert!(unframe(&framed[..framed.len() - 3]).is_none());
        // 多余字节。
        let mut extra = framed.clone();
        extra.push(0);
        assert!(unframe(&extra).is_none());
        // 翻转载荷中的一个字节：CRC 不匹配。
