    }

    #[test]
    fn stale_temp_files_are_removed_and_never_commit() {
        let dir = temp_dir();
        write_entry(&dir, 1, &dataset_of(&[("alpha", 1)])).unwrap();

        // 模拟崩溃遗留：为版本 2 写了完整临时文件但从未 rename。
