#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    // 持久化根目录是必需配置：缺失、为空或指向非目录都视为配置错误，
    // 打印一行说明后以非零码退出，不创建任何目录、不启动服务。
    let data_dir = match env::var("VDE_DATA_DIR") {
        Ok(value) if !value.is_empty() => PathBuf::from(value),
        _ => {
            eprintln!("配置错误: 必须设置环境变量 VDE_DATA_DIR 指向持久化根目录（当前未设置或为空）");
            process::exit(2);
        }
    };
    match std::fs::metadata(&data_dir) {
        Ok(meta) if meta.is_dir() => {}
        Ok(_) => {
            eprintln!(
                "配置错误: VDE_DATA_DIR 指向的不是目录: {}",
                data_dir.display()
            );
            process::exit(2);
        }
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            if let Err(e) = std::fs::create_dir_all(&data_dir) {
                eprintln!(
                    "配置错误: 无法创建持久化目录 {}: {e}",
                    data_dir.display()
                );
                process::exit(2);
            }
        }
        Err(e) => {
            eprintln!(
                "配置错误: 无法访问持久化目录 {}: {e}",
                data_dir.display()
            );
            process::exit(2);
        }
    }

    // 加载已持久化状态；目录为空时按全新实例启动（版本号从 1 开始）。
    let loaded = match persistence::load(&data_dir) {
        Ok(loaded) => loaded,
        Err(e) => {
            eprintln!("启动失败: 无法读取持久化目录 {}: {e}", data_dir.display());
            process::exit(2);
        }
    };
    let store = Store {
        dataset: loaded.dataset,
        snapshots: loaded
            .snapshots
            .into_iter()
            .map(|s| Snapshot {
                version: s.version,
                records: s.records,
            })
            .collect(),
        next_version: loaded.next_version,
    };

    let bind = env::var("VDE_BIND").unwrap_or_else(|_| "127.0.0.1:8080".to_owned());
    let listener = tokio::net::TcpListener::bind(&bind).await?;
    let state = AppState {
        store: std::sync::Arc::new(Mutex::new(store)),
        data_dir,
    };

